51	impl OsvIndex {
52	    pub(crate) fn load_from_config(config: &Config) -> Result<Option<Arc<Self>>, RegistryError> {
53	        if !config.osv.enabled {
54	            return Ok(None);
55	        }
56	        let path = config.osv.path.clone().unwrap_or_else(|| default_osv_path(config));
57	        if !path.exists() {
58	            return Err(invalid_config(format!(
59	                "OSV is enabled but database {} does not exist; download the npm OSV dump to this path or set osv.path",
60	                path.display(),
61	            )));
62	        }
63	        let index = Self::load_from_path(&path)?;
64	        // An enabled-but-empty index would make the guard a no-op and
65	        // silently disable enforcement, so treat it as misconfiguration.
66	        if index.packages.is_empty() {
67	            return Err(invalid_config(format!(
68	                "OSV is enabled but database {} yielded no npm advisories; check that the path points at the npm OSV dump",
69	                path.display(),
70	            )));
71	        }
72	        Ok(Some(Arc::new(index)))
73	    }
74	
75	    pub(crate) fn load_from_path(path: &Path) -> Result<Self, RegistryError> {
76	        if path.is_dir() {
77	            return load_from_directory(path);
78	        }
79	        // Only treat a regular file as a zip. Opening and streaming a
80	        // FIFO/socket/device for fingerprinting could block startup
81	        // indefinitely (the OSV DB loads before the listen socket binds),
82	        // so reject anything that isn't a directory or regular file.
83	        if path.is_file() {
84	            return load_from_zip(path);
85	        }
86	        Err(invalid_config(format!(
87	            "OSV database {} is neither a directory nor a regular file; point osv.path at the npm OSV dump (a .zip file or an extracted directory)",
88	            path.display(),
89	        )))
90	    }
