1913	/// Pull the on-disk packument bytes, hitting the upstream and updating
1914	/// the cache when configured. The same logic backs both the packument
1915	/// and the version-manifest endpoints.
1916	async fn load_packument_bytes(state: &AppState, name: &PackageName) -> PackumentLoad {
1917	    // A hosted packument — published here or static-served — is
1918	    // authoritative: serve it as-is and never overwrite it with an
1919	    // upstream refresh, so hosted versions can't be masked or lost.
1920	    match state.inner.storage.read_hosted_packument(name).await {
1921	        Ok(Some(bytes)) => {
1922	            record_cache_status("hosted");
1923	            return PackumentLoad::Ok(bytes);
1924	        }
1925	        Ok(None) => {}
1926	        Err(err) => {
1927	            tracing::warn!(?err, package = %name.as_str(), "published packument read failed");
