1929	    }
1930	
1931	    let Some(upstream) = resolve_upstream(state, name) else {
1932	        // Nothing published and no upstream to proxy. The only thing
1933	        // left is a leftover cache entry (e.g. a `proxy:` rule was
1934	        // removed after the package was mirrored).
1935	        return match state.inner.storage.read_cached_packument(name).await {
1936	            Ok(Some(bytes)) => {
1937	                // Served regardless of age — there's no upstream left to
1938	                // revalidate against — so this is not a fresh `hit`.
1939	                record_cache_status("orphaned");
1940	                PackumentLoad::Ok(bytes)
1941	            }
1942	            Ok(None) => PackumentLoad::NotFound,
1943	            Err(err) => PackumentLoad::Err(err),
1944	        };
1945	    };
