1947	    // Freshness window for the proxy cache: a cached packument younger
1948	    // than `ttl` is served straight from disk; older than `ttl` it's
1949	    // "stale" and revalidated against the upstream below. Lower = newer
1950	    // versions surface sooner but more upstream traffic; higher = the
1951	    // reverse. The conditional GET on the stale path keeps a high `ttl`
1952	    // cheap (a `304` refreshes the entry without re-downloading it).
1953	    //
1954	    // The uplink's per-uplink `maxage` (verdaccio) wins when set;
1955	    // otherwise the global `packument_ttl` (the `--packument-ttl-secs`
1956	    // flag) applies.
1957	    let ttl = upstream.maxage().unwrap_or(state.inner.config.packument_ttl);
1958	    // A fresh entry serves immediately (and moves its bytes out — a
1959	    // packument can be multiple MB). A stale entry yields only its
1960	    // validators; its body stays on disk until a `304`/error path below
1961	    // actually needs it, so the common stale→`200` refresh never reads it.
1962	    let validators = match state.inner.storage.read_cached_packument_entry(name, ttl).await {
1963	        Ok(Some(CachedPackument::Fresh(bytes))) => {
1964	            record_cache_status("hit");
1965	            return PackumentLoad::Ok(bytes);
1966	        }
1967	        Ok(Some(CachedPackument::Stale(validators))) => validators,
1968	        Ok(None) => CacheValidators::default(),
1969	        Err(err) => {
1970	            tracing::warn!(?err, package = %name.as_str(), "cache read failed");
1971	            CacheValidators::default()
1972	        }
1973	    };
1974	
1975	    // Revalidate conditionally when we hold a stale copy: the upstream
1976	    // can answer `304` and save us re-downloading an unchanged packument.
1977	    match upstream.fetch_packument(name, &validators).await {
1978	        Ok(PackumentFetch::Modified(fetched)) => {
1979	            store_fetched_packument(state, name, fetched).await
1980	        }
1981	        // `304` confirmed our stale copy is current: read it now (deferred
1982	        // until here), re-write it to bump the cache mtime so it's fresh
1983	        // again until the next TTL window, and serve it.
1984	        Ok(PackumentFetch::NotModified) => {
1985	            match state.inner.storage.read_cached_packument(name).await {
1986	                Ok(Some(bytes)) => {
1987	                    if let Err(err) =
1988	                        state.inner.storage.write_cached_packument(name, &bytes, &validators).await
1989	                    {
1990	                        tracing::warn!(?err, package = %name.as_str(), "packument cache refresh failed");
1991	                    }
1992	                    record_cache_status("revalidated");
1993	                    PackumentLoad::Ok(bytes)
1994	                }
1995	                // The body vanished between the freshness check and this read
1996	                // (cache wiped concurrently). The upstream just confirmed the
1997	                // package exists, so re-fetch it unconditionally and self-heal
1998	                // rather than 404-ing a present package.
1999	                Ok(None) => match upstream.fetch_packument(name, &CacheValidators::default()).await
2000	                {
2001	                    Ok(PackumentFetch::Modified(fetched)) => {
2002	                        store_fetched_packument(state, name, fetched).await
2003	                    }
2004	                    Ok(_) => PackumentLoad::NotFound,
2005	                    Err(err) => PackumentLoad::Err(err),
2006	                },
2007	                Err(err) => PackumentLoad::Err(err),
2008	            }
2009	        }
2010	        Ok(PackumentFetch::NotFound) => PackumentLoad::NotFound,
2011	        Err(err) => {
2012	            tracing::warn!(?err, package = %name.as_str(), "upstream packument fetch failed");
2013	            match state.inner.storage.read_cached_packument(name).await {
2014	                Ok(Some(bytes)) => {
2015	                    record_cache_status("stale");
2016	                    PackumentLoad::Ok(bytes)
2017	                }
2018	                // No cache to fall back on: surface the upstream failure.
2019	                Ok(None) => PackumentLoad::Err(err),
2020	                // The cache itself is unreadable: surface that I/O error
2021	                // rather than the upstream one — it's the more actionable
2022	                // failure when both go wrong.
2023	                Err(cache_err) => PackumentLoad::Err(cache_err),
2024	            }
2025	        }
2026	    }
2027	}
