371	pub fn rewrite_tarball_urls(value: &mut Value, pkg: &PackageName, public_url: &str) {
372	    let public_url = public_url.trim_end_matches('/');
373	    if let Some(versions) = value.get_mut("versions").and_then(Value::as_object_mut) {
374	        for version in versions.values_mut() {
375	            rewrite_dist_tarball(version, pkg, public_url);
376	        }
377	    }
378	    rewrite_dist_tarball(value, pkg, public_url);
379	}
380	
381	fn rewrite_dist_tarball(value: &mut Value, pkg: &PackageName, public_url: &str) {
382	    let Some(dist) = value.get_mut("dist").and_then(Value::as_object_mut) else {
383	        return;
384	    };
385	    let Some(tarball_value) = dist.get_mut("tarball") else { return };
386	    let Some(basename) = tarball_value.as_str().and_then(|url| url.rsplit('/').next()) else {
387	        return;
388	    };
389	    *tarball_value = Value::String(format!("{public_url}/{}/-/{basename}", pkg.as_str()));
390	}
