392	/// Look up the version manifest for `version_or_tag` inside a parsed
393	/// packument: if the string matches a dist-tag it resolves through
394	/// `dist-tags[tag]` first, otherwise it's taken as a literal version.
395	/// Returns the version's manifest *with* the `dist.tarball` rewritten
396	/// to point at this server.
397	pub fn extract_version_manifest(
398	    packument: &Value,
399	    pkg: &PackageName,
400	    version_or_tag: &str,
401	    public_url: &str,
402	) -> Option<Value> {
403	    let resolved = packument
404	        .get("dist-tags")
405	        .and_then(|tags| tags.get(version_or_tag))
406	        .and_then(Value::as_str)
407	        .unwrap_or(version_or_tag);
408	    let mut manifest = packument.get("versions")?.get(resolved)?.clone();
409	    rewrite_tarball_urls(&mut manifest, pkg, public_url);
410	    Some(manifest)
411	}
