464	/// Strip a parsed packument down to the abbreviated install-v1 form.
465	/// Should be called *after* `rewrite_tarball_urls` so the returned
466	/// document's `dist.tarball` URLs already point at this server.
467	pub fn abbreviate_packument(packument: &Value, now: DateTime<Utc>) -> Value {
468	    let mut out = serde_json::Map::new();
469	    if let Some(obj) = packument.as_object() {
470	        for &field in ABBREVIATED_TOP_FIELDS {
471	            if let Some(value) = obj.get(field) {
472	                out.insert(field.to_string(), value.clone());
473	            }
474	        }
475	        // Coarsen `time`, then synthesize `modified` from the
476	        // coarsened map — npm packuments nest `modified` under `time`
477	        // and pacquet's resolver reads it at the top level.
478	        if let Some(time) = obj.get("time").and_then(Value::as_object) {
479	            let time = coarsen_time_map(time, now);
480	            if let Some(modified) = time.get("modified") {
481	                out.insert("modified".to_string(), modified.clone());
482	            }
483	            out.insert("time".to_string(), Value::Object(time));
484	        }
485	        if let Some(versions) = obj.get("versions").and_then(Value::as_object) {
486	            let mut abbreviated_versions = serde_json::Map::with_capacity(versions.len());
487	            for (version_id, version_value) in versions {
488	                let Some(version_obj) = version_value.as_object() else { continue };
489	                let mut trimmed = serde_json::Map::new();
490	                for &field in ABBREVIATED_VERSION_FIELDS {
491	                    if let Some(value) = version_obj.get(field) {
492	                        trimmed.insert(field.to_string(), value.clone());
493	                    }
494	                }
495	                trim_dist_fields(&mut trimmed);
496	                abbreviated_versions.insert(version_id.clone(), Value::Object(trimmed));
497	            }
498	            out.insert("versions".to_string(), Value::Object(abbreviated_versions));
499	        }
500	    }
501	    Value::Object(out)
502	}
