504	/// Trim `dist` subfields the resolver and installer never read:
505	///
506	/// * `npm-signature` — the legacy PGP detached signature. npm stopped
507	///   populating it years ago in favour of the ECDSA `signatures`, and
508	///   nothing in pnpm or pacquet reads it.
509	/// * `shasum` — the legacy sha1 hash, redundant once `integrity` (SRI)
510	///   is present. "Present" mirrors pnpm's `getIntegrity` truthiness
511	///   check (`if (dist.integrity)`): a non-empty string. An absent,
512	///   empty, or non-string `integrity` keeps `shasum` so pnpm's
513	///   sha1 fallback still has a hash (pre-2017 publishes).
514	///
515	/// `dist.signatures` (the ECDSA registry signatures) is deliberately
516	/// preserved: it binds `name@version:integrity` to the upstream
517	/// registry's key and is the input to a potential client-side
518	/// install-time verification on the pnpr path.
519	///
520	/// `unpackedSize` and `fileCount` are preserved: pacquet reads both
521	/// off the resolver-fetched manifest — `unpackedSize` sizes the
522	/// decompression buffer, and together they form the download's
523	/// queueing priority (the estimated pipeline work that starts the
524	/// most expensive tarballs first).
525	fn trim_dist_fields(version: &mut serde_json::Map<String, Value>) {
526	    let Some(dist) = version.get_mut("dist").and_then(Value::as_object_mut) else {
527	        return;
528	    };
529	    dist.remove("npm-signature");
530	    if dist.get("integrity").and_then(Value::as_str).is_some_and(|integrity| !integrity.is_empty())
531	    {
532	        dist.remove("shasum");
533	    }
534	}
